code.java:
class Solution {
    public int arrayPairSum(int[] nums){
        Arrays.sort(nums);
        int answer=0;
        for(int i=0;i<nums.length;i+=2)answer+=nums[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun arrayPairSum(nums:IntArray):Int{
        nums.sort();
        var answer=0;
        for(i in nums.indices step 2)answer+=nums[i];
        return answer
    }
}

code.cpp:
class Solution {
    public: int arrayPairSum(vector<int>& nums){
        sort(nums.begin(),nums.end());
        int answer=0;
        for(int i=0;i<(int)nums.size();i+=2)answer+=nums[i];
        return answer;
    }
};
